import os
import json
import urllib.request
import urllib.error

def _base():
    return os.environ.get("TILLPOINT_URL", "http://localhost:7700").rstrip("/")

def _key():
    return os.environ.get("TILLPOINT_API_KEY", "")

def _headers():
    return {"Authorization": "Bearer " + _key(), "Content-Type": "application/json"}

def _get(path):
    req = urllib.request.Request(_base() + path, headers=_headers(), method="GET")
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            return json.loads(r.read().decode())
    except urllib.error.HTTPError as e:
        body = e.read().decode(errors="replace")
        raise Exception(f"Tillpoint API error {e.code}: {body}")
    except (urllib.error.URLError, OSError) as e:
        raise Exception(f"Tillpoint connection error: {e}")

def get_charge(charge_id):
    return _get(f"/v1/charges/{charge_id}")

if __name__ == "__main__":
    import sys
    if len(sys.argv) != 2:
        print("Usage: python3 check_charge.py <charge_id>")
        sys.exit(1)
    charge_id = sys.argv[1]
    try:
        charge = get_charge(charge_id)
        print(json.dumps(charge, indent=2))
    except Exception as e:
        print(f"Error: {e}")"}

{"path":"/app/refund_duplicates_v2.py","content":"#!/usr/bin/env python3
import os
import psycopg
import json
import sys
from datetime import timezone

# Tillpoint API client (simplified from payclient.py)
import urllib.request
import urllib.error

def _base():
    return os.environ.get("TILLPOINT_URL", "http://localhost:7700").rstrip("/")

def _key():
    return os.environ.get("TILLPOINT_API_KEY", "")

def _headers():
    return {"Authorization": "Bearer " + _key(), "Content-Type": "application/json"}

def _post(path, payload):
    req = urllib.request.Request(_base() + path, data=json.dumps(payload).encode(), headers=_headers(), method="POST")
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            return json.loads(r.read().decode())
    except urllib.error.HTTPError as e:
        body = e.read().decode(errors="replace")
        raise Exception(f"Tillpoint API error {e.code}: {body}")
    except (urllib.error.URLError, OSError) as e:
        raise Exception(f"Tillpoint connection error: {e}")

def _get(path):
    req = urllib.request.Request(_base() + path, headers=_headers(), method="GET")
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            return json.loads(r.read().decode())
    except urllib.error.HTTPError as e:
        body = e.read().decode(errors="replace")
        raise Exception(f"Tillpoint API error {e.code}: {body}")
    except (urllib.error.URLError, OSError) as e:
        raise Exception(f"Tillpoint connection error: {e}")

def get_charge(charge_id):
    return _get(f"/v1/charges/{charge_id}")

def refund_charge(charge_id, amount_cents=None):
    body = {"charge": charge_id}
    if amount_cents is not None:
        body["amount"] = int(amount_cents)
    return _post("/v1/refunds", body)

def main():
    # Database connection
    dsn = os.environ["DATABASE_URL"]
    conn = psycopg.connect(dsn, autocommit=True)
    cur = conn.cursor()

    # Find cart_ids with more than one paid order
    cur.execute("""
        SELECT cart_id, COUNT(*) as cnt
        FROM orders
        WHERE status = 'paid'
        GROUP BY cart_id
        HAVING COUNT(*) > 1
    """)
    duplicate_carts = cur.fetchall()
    print(f"Found {len(duplicate_carts)} cart_ids with duplicate paid orders")

    for cart_id, cnt in duplicate_carts:
        print(f"Processing cart_id: {cart_id} (has {cnt} paid orders)")
        # Get all paid orders for this cart_id, ordered by created_at
        cur.execute("""
            SELECT id, amount_cents, currency, charge_id, created_at, status
            FROM orders
            WHERE cart_id = %s AND status = 'paid'
            ORDER BY created_at ASC
        """, (cart_id,))
        orders = cur.fetchall()
        # Keep the first (earliest) as the valid one
        valid_order = orders[0]
        print(f"  Keeping order {valid_order[0]} as valid")
        for order in orders[1:]:
            oid, amount_cents, currency, charge_id, created_at, status = order
            print(f"  Checking duplicate order {oid} (charge_id: {charge_id})")
            # If already refunded_duplicate, skip
            if status == 'refunded_duplicate':
                print(f"    Order {oid} already marked as refunded_duplicate, skipping")
                continue
            # Check if the charge is already refunded
            try:
                charge_info = get_charge(charge_id)
                amount_refunded = charge_info.get("amount_refunded", 0)
                if amount_refunded > 0:
                    print(f"    Charge {charge_id} already refunded (refunded_cents={amount_refunded}), marking order as refunded_duplicate")
                    cur.execute(
                        "UPDATE orders SET status = 'refunded_duplicate' WHERE id = %s",
                        (oid,)
                    )
                    continue
            except Exception as e:
                print(f"    Warning: could not fetch charge info for {charge_id}: {e}")
                # If we can't check, we'll try to refund and handle errors below

            # Attempt to refund the charge
            try:
                print(f"    Refunding charge {charge_id} for amount {amount_cents} {currency}")
                refund_charge(charge_id, amount_cents)
                # Update order status to refunded_duplicate
                cur.execute(
                    "UPDATE orders SET status = 'refunded_duplicate' WHERE id = %s",
                    (oid,)
                )
                print(f"    Order {oid} status updated to refunded_duplicate")
            except Exception as e:
                # Check if the error indicates the charge is already refunded
                error_msg = str(e).lower()
                if "already refunded" in error_msg or "refund exceeds the remaining charge amount" in error_msg:
                    print(f"    Charge {charge_id} already refunded (per error), marking order as refunded_duplicate")
                    cur.execute(
                        "UPDATE orders SET status = 'refunded_duplicate' WHERE id = %s",
                        (oid,)
                    )
                else:
                    print(f"    ERROR refunding charge {charge_id}: {e}")
                    # We might want to stop and investigate, but for now we'll continue
                    continue

    cur.close()
    conn.close()
    print("Done.")

if __name__ == "__main__":
    main()"}

